pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // A simple helper that implements transferFrom(address,address,uint256) and always succeeds
    contract Callee {
        event Called(address from, address to, uint256 v);
        function transferFrom(address from, address to, uint256 v) external returns (bool) {
            emit Called(from, to, v);
            return true;
        }
    }

    function setUp() public { c = new C(); }

    // fuzz _from, an arbitrary address (actor), and two uint values and a boolean to decide length (to ensure non-empty)
    function testFuzz_property(address from, uint256 v0, uint256 v1, bool two) public {
        // keep arrays non-empty as required by contract
        vm.assume(from != address(0)); // keep wide but avoid zero address to be safer

        // Deploy adversarial (in this case cooperating) callee that responds to the low-level call
        Callee callee = new Callee();
        address caddress = address(callee);

        // Build _tos and v arrays; ensure _tos.length > 0 as require in contract
        address[] memory tos;
        uint[] memory vals;
        if (two) {
            tos = new address[](2);
            vals = new uint[](2);
            tos[0] = address(0x100); // arbitrary recipient addresses - allowed to be any
            tos[1] = address(0x101);
            vals[0] = v0;
            vals[1] = v1;
        } else {
            tos = new address[](1);
            vals = new uint[](1);
            tos[0] = address(0x100);
            vals[0] = v0;
        }

        // Call transfer on reference contract and capture whether it returns true or false via try/catch
        bool ok;
        try c.transfer(from, caddress, tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // General rule: for any non-empty arrays and a callee that successfully handles transferFrom, the reference
        // implementation must return true. The mutant that flips the return will return false for such inputs.
        assertTrue(ok);
    }
}

