contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from (address), callee (address via deployed helper), tos array and vals array
    function testFuzz_property(address from, address /*unused*/, address[] memory _tos, uint256[] memory v) public {
