        vm.assume(_tos.length > 0 && _tos.length == v.length);

        // Deploy a helper that always succeeds on the transferFrom selector
        SucceedsHelper h = new SucceedsHelper();
        address callee = address(h);

        // Call transfer and observe the boolean result via try/catch to read returned value
