// Helper that emulates an external contract whose transferFrom call always succeeds
contract SucceedsHelper {
    // respond to any selector and return true (encoded as single bool true)
    fallback() external payable returns (bytes memory) {
        // return abi.encode(true) so low-level call succeeds and the caller's require(_s) is satisfied
        return abi.encode(true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller, the list length and amounts; we deploy a callee that always succeeds
    function testFuzz_property(address from, uint256 len, uint256 seed) public {
        // keep length reasonable but allow zero (we will assume non-zero for the property)
        uint256 n = bound(len, 0, 8);
        // require non-empty per contract's require
        vm.assume(n > 0);

        // build arrays
        address[] memory tos = new address[](n);
        uint[] memory vals = new uint[](n);

        // deploy a helper callee that always returns success for any call
        AlwaysSucceeds suc = new AlwaysSucceeds();

        for (uint i = 0; i < n; i++) {
            tos[i] = address(suc);
            // derive amounts from seed so fuzzer can vary them
            vals[i] = uint(keccak256(abi.encodePacked(seed, i)));
        }

        // call transfer and observe returned boolean via try/catch since it's external
        bool ok;
        try c.transfer(from, address(suc), tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            // any revert would violate preconditions; but our setup ensures suc succeeds
            ok = false;
        }

        // General fact: for any non-empty tos and when every external call succeeds (our AlwaysSucceeds),
        // the correct C returns true. The mutant returns false for some such inputs. Assert that ok is true.
        assertTrue(ok);
    }
}

// adversarial helper that always returns success for low-level calls
contract AlwaysSucceeds {
    // accept any calldata and return non-empty success bytes
    fallback() external payable returns (bytes memory) {
        return abi.encodePacked(uint256(1));
    }
    receive() external payable {}
}
